    async function worker() {
        while (currentIndex < taskGenerators.length) {
            const index = currentIndex++;
            const task = taskGenerators[index];
            try {
                results[index] = await task();
            } catch (error) {
                // We capture the error but don't stop the other workers
                results[index] = { error };
            }
