    // Start up to 'concurrencyLimit' workers
    const workers = [];
    for (let i = 0; i < concurrencyLimit && i < taskGenerators.length; i++) {
        workers.push(worker());
    }
    
    // Wait for all workers to finish
    await Promise.all(workers);
    
    return results;
